const AGENT_ID = '';
const AGENT_PHONE_NUMBER_ID = '';
const PROVIDER = 'twilio';
const ORG = '11111111-1111-1111-1111-111111111111';

const body = $input.first().json.body ?? $input.first().json;
const errors = [];
const agentId = String(body.agent_id || AGENT_ID).trim();
const phoneNumberId = String(body.agent_phone_number_id || AGENT_PHONE_NUMBER_ID).trim();
const provider = String(body.provider || PROVIDER).trim();
const patientName = String(body.patient_name || '').trim();
const reason = String(body.reason || '').trim();
const phoneRaw = String(body.phone || body.to_number || '').trim();
const digits = phoneRaw.replace(/[^0-9]/g, '');
const phone = `+${digits}`;

if (!agentId) errors.push('Set AGENT_ID in Prepare Outbound Call, or send agent_id.');
if (!phoneNumberId) errors.push('Set AGENT_PHONE_NUMBER_ID in Prepare Outbound Call, or send agent_phone_number_id.');
if (/^\+?\d{7,}$/.test(phoneNumberId)) errors.push('AGENT_PHONE_NUMBER_ID must be the ElevenLabs phone number id (it starts with phnum_), not the +1 phone number.');
if (!['twilio', 'sip_trunk'].includes(provider)) errors.push('provider must be twilio or sip_trunk.');
if (!patientName) errors.push('patient_name is required.');
if (!reason) errors.push('reason is required.');
if (digits.length < 7) errors.push('phone must include at least 7 digits.');

const urls = {
  twilio: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
  sip_trunk: 'https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call'
};
const firstName = patientName.split(/\s+/)[0];

return [{
  json: {
    _valid: errors.length === 0,
    _errors: errors,
    elevenlabs_url: urls[provider] || urls.twilio,
    elevenlabs_body: {
      agent_id: agentId,
      agent_phone_number_id: phoneNumberId,
      to_number: phone,
      conversation_initiation_client_data: {
        dynamic_variables: {
          organization_id: String(body.organization_id || ORG).trim(),
          direction: 'outbound',
          patient_name: patientName,
          caller_name: patientName,
          call_reason: reason,
          opening_line: `Hi ${firstName}, this is Maple Grove Dental Clinic calling about ${reason}. Do you have a moment?`
        }
      }
    }
  }
}];

function asText(value) {
  if (value == null || value === '') return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(asText).filter(Boolean).join(' ');
  if (typeof value === 'object') return asText(value.message || value.msg || value.status || value.error || value.description) || JSON.stringify(value);
  return String(value);
}
let payload = $json.body !== undefined ? $json.body : $json;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = { message: payload }; }
}
if (payload && payload.body !== undefined && (payload.statusCode || payload.status)) {
  payload = payload.body;
  if (typeof payload === 'string') {
    try { payload = JSON.parse(payload); } catch (e) { payload = { message: payload }; }
  }
}
const status = Number($json.statusCode || $json.status || 0);
const detail = asText(payload && payload.detail) || asText(payload && payload.error) || asText($json.error);
const upstream = asText(payload && payload.message);
const ok = status >= 200 && status < 300 && (!payload || payload.success !== false);
let failure = upstream || detail;
if (!failure || failure === '{}') failure = `ElevenLabs did not start the call (HTTP ${status}).`;
if (/first_message|override/i.test(failure)) failure += ' The greeting is the opening_line variable, so leave the first-message override off.';
if (/sip/i.test(failure)) failure += ' In Prepare Outbound Call, set PROVIDER to sip_trunk.';
return [{
  json: {
    success: ok,
    conversation_id: (payload && payload.conversation_id) || null,
    message: ok ? (upstream || 'Outbound call started.') : failure,
    status_code: 200
  }
}];
